import sys

lines = sys.stdin.read().split("\n")
counts = {"ERROR": 0, "WARN": 0, "INFO": 0}
for line in lines[1 : int(lines[0]) + 1]:
    level = line.split()[1]
    if level in counts:
        counts[level] += 1
