import sys


def valid(text):
    parts = text.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not all("0" <= ch <= "9" for ch in part):
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True


data = sys.stdin.read().split()
for text in data[1 : int(data[0]) + 1]:
    print("YES" if valid(text) else "NO")

