import sys

data = sys.stdin.read().split()
streak = {}
locked = set()
for i in range(int(data[0])):
    user, result = data[1 + 2 * i], data[2 + 2 * i]
    if result == "OK":
        streak[user] = 0
    else:
        streak[user] = streak.get(user, 0) + 1
        if streak[user] == 3:
            locked.add(user)
